-- AURA kids: business schema for a function_backend site.
-- Access policies are generated by the platform (accessPolicies: []); no DML here.

CREATE TABLE app.users (
  id uuid PRIMARY KEY,
  email text NOT NULL UNIQUE,
  name text NOT NULL,
  phone text,
  password_salt text NOT NULL,
  password_hash text NOT NULL,
  password_iterations integer NOT NULL,
  role text NOT NULL CHECK (role IN ('client', 'admin', 'owner')),
  created_at timestamptz NOT NULL
);

-- Only token digests are stored; plaintext session tokens never reach the database.
CREATE TABLE app.sessions (
  token_digest text PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app.users (id),
  created_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz
);

CREATE TABLE app.auth_limiter (
  key text PRIMARY KEY,
  window_started_at timestamptz NOT NULL,
  attempt_count integer NOT NULL
);

CREATE TABLE app.services (
  id uuid PRIMARY KEY,
  title text NOT NULL,
  title_kk text,
  title_en text,
  category text NOT NULL,
  description text NOT NULL,
  description_kk text,
  description_en text,
  duration_min integer NOT NULL,
  price integer NOT NULL,
  image text NOT NULL,
  popular boolean NOT NULL,
  active boolean NOT NULL,
  sort_order integer NOT NULL,
  created_at timestamptz NOT NULL
);

CREATE TABLE app.bookings (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app.users (id),
  service_id uuid NOT NULL REFERENCES app.services (id),
  booking_date text NOT NULL,
  slot text NOT NULL,
  status text NOT NULL,
  participants text NOT NULL,
  client_name text NOT NULL,
  client_phone text NOT NULL,
  payment_method text NOT NULL CHECK (payment_method IN ('card', 'cash')),
  comment text,
  price integer NOT NULL,
  created_at timestamptz NOT NULL
);

CREATE INDEX bookings_user_created_idx ON app.bookings (user_id, created_at);
CREATE INDEX bookings_date_idx ON app.bookings (booking_date);

-- Parent reviews shown on the site. Author name is a snapshot taken at posting;
-- moderation hides a comment without destroying its history.
CREATE TABLE app.comments (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app.users (id),
  service_id uuid REFERENCES app.services (id) ON DELETE SET NULL,
  author_name text NOT NULL,
  rating integer NOT NULL,
  body text NOT NULL,
  status text NOT NULL,
  reply_body text,
  reply_by uuid REFERENCES app.users (id) ON DELETE SET NULL,
  replied_at timestamptz,
  created_at timestamptz NOT NULL
);

CREATE INDEX comments_created_idx ON app.comments (created_at);

-- Atomic slot claim: the composite primary key rejects a second booking for the
-- same service/date/time even under concurrent requests.
CREATE TABLE app.slot_holds (
  service_id uuid NOT NULL,
  booking_date text NOT NULL,
  slot text NOT NULL,
  booking_id uuid NOT NULL,
  PRIMARY KEY (service_id, booking_date, slot)
);

-- A storyboard of the homepage: the studio team composes photos, titles and
-- descriptions here, and the public page renders only active rows in order.
-- Images are either bundled scene keys (k-hero) or bounded base64 data URLs.
CREATE TABLE app.gallery_items (
  id uuid PRIMARY KEY,
  title text NOT NULL,
  title_kk text,
  title_en text,
  description text NOT NULL,
  description_kk text,
  description_en text,
  image text NOT NULL,
  active boolean NOT NULL,
  sort_order integer NOT NULL,
  created_at timestamptz NOT NULL
);

CREATE INDEX gallery_items_sort_idx ON app.gallery_items (sort_order);

-- Requests left on the homepage for one or several children. A signed-in guest
-- links the request to their account; once staff marks it "contacted" the account
-- owner confirms it, which flips the status to "confirmed".
CREATE TABLE app.orders (
  id uuid PRIMARY KEY,
  user_id uuid REFERENCES app.users (id) ON DELETE SET NULL,
  name text NOT NULL,
  phone text NOT NULL,
  participants text NOT NULL,
  service_id uuid REFERENCES app.services (id) ON DELETE SET NULL,
  comment text,
  status text NOT NULL CHECK (status IN ('new', 'contacted', 'confirmed', 'done', 'cancelled')),
  confirmed_at timestamptz,
  created_at timestamptz NOT NULL
);

CREATE INDEX orders_created_idx ON app.orders (created_at);
CREATE INDEX orders_user_idx ON app.orders (user_id);